fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn tri(t: i32, span: i32) -> i32 {
    let period: i32 = span * 2;
    let phase: i32 = t % period;
    if phase < span { phase } else { period - phase }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x081018);
    let mut i: i32 = 0;
    while i < 40 {
        let speed: i32 = hash(i * 5 + 2) % 2 + 1;
        let sway: i32 = tri(t + hash(i * 9 + 4) % 32, 16) - 8;
        let x: i32 = (hash(i * 13 + 1) % w + sway + w) % w;
        let y: i32 = (hash(i * 11 + 7) + t * speed) % h;
        let size: i32 = speed + 1;
        let c: i32 = if speed == 2 { 0xffffff } else { 0xa0a8b0 };
        host::display::fill_rect(x, y, size, size, c);
        i = i + 1;
    }
    host::display::present();
}
